window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-cda01519cef64559"]={"versions": [{"id": "FIG-cda01519cef64559", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Prozessdiagramm nach der Software &amp; Systems Process Engineering Metamodel (SPEM) Notation im Kontext von AUTOSAR Timing Analysis. Das Diagramm modelliert den Steuergeräte-Anwendungsfall (ECU Use-Case) „Validation of Timing“ zur Verifikation von Timing-Eigenschaften gegen vorgegebene Anforderungen auf Basis modell- und implementationsgestützter Analysen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modell umfasst Aktivitäten (Task Definitions) und Arbeitsergebnisse (Work Products / Work Product Uses):</p>\n<ul class=\"fig-list\"><li>Aktivitäten (gekennzeichnet durch fünfeckige Pfeilsymbole):\n<ul class=\"fig-list\"><li><code>Perform Implementation-Based Timing Analysis</code>: Führt timingbezogene Analysen auf Basis der Implementierung durch.\n</li><li><code>Perform Model-Based Timing Analysis</code>: Führt Timing-Analysen auf Basis des Timing-Modells durch.\n</li><li><code>Verify Timing</code>: Verifiziert die Analyseergebnisse gegen spezifizierte Anforderungen.\n</li></ul>\n</li><li>Arbeitsergebnisse (gekennzeichnet durch Dokumentsymbole):\n<ul class=\"fig-list\"><li><code>Implementation</code>: Eingangsartefakt für die implementationsbasierte Analyse.\n</li><li><code>Timing Model</code>: Eingangsartefakt für die modellbasierte Analyse.\n</li><li><code>Timing Requirements</code>: Spezifikation der einzuhaltenden Timing-Anforderungen.\n</li><li><code>Timing Analysis Report</code>: Zwischenergebnis, das die Resultate der modell- oder implementationsbasierten Analysen zusammenfasst.\n</li><li><code>Timing Verification Report</code>: Endergebnis der Verifikationsaktivität.\n</li></ul>\n</li><li>Schnittstellen und Rollen:\n<ul class=\"fig-list\"><li>Stereotyp <code>«input»</code>: Eingehende Artefakt-Assoziationen von <code>Implementation</code> zu <code>Perform Implementation-Based Timing Analysis</code>, von <code>Timing Model</code> zu <code>Perform Model-Based Timing Analysis</code>, sowie von <code>Timing Analysis Report</code> und <code>Timing Requirements</code> zu <code>Verify Timing</code>.\n</li><li>Stereotyp <code>«output»</code>: Ausgehende Artefakt-Assoziationen von <code>Perform Implementation-Based Timing Analysis</code> und <code>Perform Model-Based Timing Analysis</code> zu <code>Timing Analysis Report</code>, sowie von <code>Verify Timing</code> zu <code>Timing Verification Report</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Steuergeräte-Ablauf gliedert sich in parallele bzw. alternative Analysepfade und eine nachgelagerte Verifikationsstufe:</p>\n<ol class=\"fig-list\"><li>Analyse:\n<ul class=\"fig-list\"><li>Entweder wird auf Basis der <code>Implementation</code> die Aktivität <code>Perform Implementation-Based Timing Analysis</code> ausgeführt,\n</li><li>oder auf Basis des <code>Timing Model</code> die Aktivität <code>Perform Model-Based Timing Analysis</code>.\n</li><li>Beide Pfade erzeugen als Ergebnis ein <code>Timing Analysis Report</code>-Artefakt.\n</li></ul>\n</li><li>Verifikation:\n<ul class=\"fig-list\"><li>Die Aktivität <code>Verify Timing</code> nimmt den <code>Timing Analysis Report</code> sowie die <code>Timing Requirements</code> als Eingangsdaten entgegen.\n</li><li>Der Abgleich der ermittelten Timing-Werte mit den geforderten Vorgaben führt zur Erstellung des finalen <code>Timing Verification Report</code>.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm besitzt methodischen und prozessualen Charakter innerhalb des Technical Reports zur Timing-Analyse. Es definiert verbindliche Rollen von Eingangs- und Ausgangsdaten für Werkzeuge und Entwicklungsprozesse beim Timing-Nachweis. Bei der Werkzeugkettenintegration müssen Schnittstellen bereitgestellt werden, die Analyseergebnisse (<code>Timing Analysis Report</code>) und Soll-Vorgaben (<code>Timing Requirements</code>) standardkonform konsolidieren und maschinenlesbar verifizierbar machen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-28069a934982cee5", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Prozessdiagramm nach der Software &amp; Systems Process Engineering Metamodel (SPEM) Notation im Kontext von AUTOSAR Timing Analysis. Das Diagramm modelliert den Steuergeräte-Anwendungsfall (ECU Use-Case) „Validation of Timing“ zur Verifikation von Timing-Eigenschaften gegen vorgegebene Anforderungen auf Basis modell- und implementationsgestützter Analysen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modell umfasst Aktivitäten (Task Definitions) und Arbeitsergebnisse (Work Products / Work Product Uses):</p>\n<ul class=\"fig-list\"><li>Aktivitäten (gekennzeichnet durch fünfeckige Pfeilsymbole):\n<ul class=\"fig-list\"><li><code>Perform Implementation-Based Timing Analysis</code>: Führt timingbezogene Analysen auf Basis der Implementierung durch.\n</li><li><code>Perform Model-Based Timing Analysis</code>: Führt Timing-Analysen auf Basis des Timing-Modells durch.\n</li><li><code>Verify Timing</code>: Verifiziert die Analyseergebnisse gegen spezifizierte Anforderungen.\n</li></ul>\n</li><li>Arbeitsergebnisse (gekennzeichnet durch Dokumentsymbole):\n<ul class=\"fig-list\"><li><code>Implementation</code>: Eingangsartefakt für die implementationsbasierte Analyse.\n</li><li><code>Timing Model</code>: Eingangsartefakt für die modellbasierte Analyse.\n</li><li><code>Timing Requirements</code>: Spezifikation der einzuhaltenden Timing-Anforderungen.\n</li><li><code>Timing Analysis Report</code>: Zwischenergebnis, das die Resultate der modell- oder implementationsbasierten Analysen zusammenfasst.\n</li><li><code>Timing Verification Report</code>: Endergebnis der Verifikationsaktivität.\n</li></ul>\n</li><li>Schnittstellen und Rollen:\n<ul class=\"fig-list\"><li>Stereotyp <code>«input»</code>: Eingehende Artefakt-Assoziationen von <code>Implementation</code> zu <code>Perform Implementation-Based Timing Analysis</code>, von <code>Timing Model</code> zu <code>Perform Model-Based Timing Analysis</code>, sowie von <code>Timing Analysis Report</code> und <code>Timing Requirements</code> zu <code>Verify Timing</code>.\n</li><li>Stereotyp <code>«output»</code>: Ausgehende Artefakt-Assoziationen von <code>Perform Implementation-Based Timing Analysis</code> und <code>Perform Model-Based Timing Analysis</code> zu <code>Timing Analysis Report</code>, sowie von <code>Verify Timing</code> zu <code>Timing Verification Report</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Steuergeräte-Ablauf gliedert sich in parallele bzw. alternative Analysepfade und eine nachgelagerte Verifikationsstufe:</p>\n<ol class=\"fig-list\"><li>Analyse:\n<ul class=\"fig-list\"><li>Entweder wird auf Basis der <code>Implementation</code> die Aktivität <code>Perform Implementation-Based Timing Analysis</code> ausgeführt,\n</li><li>oder auf Basis des <code>Timing Model</code> die Aktivität <code>Perform Model-Based Timing Analysis</code>.\n</li><li>Beide Pfade erzeugen als Ergebnis ein <code>Timing Analysis Report</code>-Artefakt.\n</li></ul>\n</li><li>Verifikation:\n<ul class=\"fig-list\"><li>Die Aktivität <code>Verify Timing</code> nimmt den <code>Timing Analysis Report</code> sowie die <code>Timing Requirements</code> als Eingangsdaten entgegen.\n</li><li>Der Abgleich der ermittelten Timing-Werte mit den geforderten Vorgaben führt zur Erstellung des finalen <code>Timing Verification Report</code>.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm besitzt methodischen und prozessualen Charakter innerhalb des Technical Reports zur Timing-Analyse. Es definiert verbindliche Rollen von Eingangs- und Ausgangsdaten für Werkzeuge und Entwicklungsprozesse beim Timing-Nachweis. Bei der Werkzeugkettenintegration müssen Schnittstellen bereitgestellt werden, die Analyseergebnisse (<code>Timing Analysis Report</code>) und Soll-Vorgaben (<code>Timing Requirements</code>) standardkonform konsolidieren und maschinenlesbar verifizierbar machen.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-cda01519cef64559", "to": "FIG-28069a934982cee5", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
